/* prog48_sorted_linked_list.c
 *
 * Re‑implementation of the original program (observed via reverse‑engineering).
 * The program reads up to 64 signed decimal integers from the command line,
 * stores them in a singly‑linked list kept in ascending order, and then
 * prints the list contents separated by spaces.  If no numbers are supplied
 * it prints the word “EMPTY”.
 *
 * The implementation follows the logic uncovered in the decompiled binary,
 * but is written in clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_ELEMS 64          /* maximum number of values the program accepts */

static long  value[MAX_ELEMS];   /* stored numbers */
static int   next[MAX_ELEMS];    /* linked‑list “next” indices */
static int   head = -1;          /* index of first element, -1 = empty */
static int   used = 0;           /* how many elements have been stored */

/* Insert a new value into the sorted linked list (ascending order). */
static void insert_sorted(long v)
{
    if (used >= MAX_ELEMS)               /* safety – should never happen */
        return;

    int idx = used++;                     /* index for the new node */
    value[idx] = v;
    next[idx]  = -1;

    /* Empty list – new node becomes the head */
    if (head == -1 || value[head] > v) {
        next[idx] = head;
        head = idx;
        return;
    }

    /* Find the insertion point: first node whose successor is larger */
    int cur = head;
    while (next[cur] != -1 && value[next[cur]] <= v) {
        cur = next[cur];
    }

    /* Insert after ‘cur’ */
    next[idx] = next[cur];
    next[cur] = idx;
}

/* Print the list contents. */
static void print_list(void)
{
    if (head == -1) {
        puts("EMPTY");
        return;
    }

    bool first = true;
    for (int cur = head; cur != -1; cur = next[cur]) {
        if (!first)
            putchar(' ');
        printf("%ld", value[cur]);
        first = false;
    }
    putchar('\n');
}

/* ---------------------------------------------------------------------- */
int main(int argc, char **argv)
{
    /* Build the sorted list from command‑line arguments */
    for (int i = 1; i < argc && used < MAX_ELEMS; ++i) {
        char *endptr = NULL;
        long v = strtol(argv[i], &endptr, 10);
        (void)endptr;          /* silence unused‑variable warning */
        insert_sorted(v);
    }

    /* Output the result */
    print_list();
    return 0;
}
